VALUES
  ('cairo_citadel', 'Salah El-Din Citadel', 'Salah El-Din Citadel', 'قلعة صلاح الدين الأيوبي', 'An Ayyubid hilltop fortress later expanded in the Ottoman era, home to the Mosque of Muhammad Ali and sweeping panoramic views across Cairo.', 'An Ayyubid hilltop fortress later expanded in the Ottoman era, home to the Mosque of Muhammad Ali and sweeping panoramic views across Cairo.', 'قلعة حصينة على التل شُيّدت في العصر الأيوبي وطُوّرت في العصر العثماني، وتضم مسجد محمد علي وتطل بإطلالات بانورامية على القاهرة.', 'https://upload.wikimedia.org/wikipedia/commons/e/ef/Cairo_Citadel_1.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original', ARRAY['https://upload.wikimedia.org/wikipedia/commons/e/ef/Cairo_Citadel_1.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original']::text[], 4.8, 'Historical', 'تاريخي', 30.0287, 31.2599, 'Al Abageyah, Cairo', 'الأباجية، القاهرة', '8:00 AM - 5:00 PM', 12500, 'cheap', 'Paid admission; verify current ticket prices', 60, 550, FALSE, FALSE, 999, TRUE, TRUE, 'cairo'),
  ('khan_el_khalili', 'Khan El-Khalili Bazaar', 'Khan El-Khalili Bazaar', 'خان الخليلي', 'A historic Mamluk-era bazaar in Al-Gamaliya, known for brassware, lanterns, spices, traditional crafts, and heritage cafes in the heart of Islamic Cairo.', 'A historic Mamluk-era bazaar in Al-Gamaliya, known for brassware, lanterns, spices, traditional crafts, and heritage cafes in the heart of Islamic Cairo.', 'بازار تاريخي يعود إلى العصر المملوكي في الجمالية، يشتهر بالمشغولات النحاسية والفوانيس والتوابل والحرف التقليدية والمقاهي التراثية.', 'https://upload.wikimedia.org/wikipedia/commons/e/ed/Cairo_-_Khan_el-Khalili_bazaar%2C_2008_Dec_08_%283163072544%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original', ARRAY['https://upload.wikimedia.org/wikipedia/commons/e/ed/Cairo_-_Khan_el-Khalili_bazaar%2C_2008_Dec_08_%283163072544%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original']::text[], 4.7, 'Shopping', 'تسوّق', 30.0477, 31.2623, 'Al-Gamaliya, Cairo', 'الجمالية، القاهرة', '10:00 AM - 11:00 PM', 9800, 'free', 'Free entry; purchases vary', 0, 0, FALSE, FALSE, 999, TRUE, TRUE, 'cairo'),
  ('al_muizz_street', 'Al-Muizz Street', 'Al-Muizz Street', 'شارع المعز لدين الله الفاطمي', 'An open-air museum of medieval Fatimid and Mamluk architecture, connecting Bab al-Futuh in the north with Bab Zuweila in the south.', 'An open-air museum of medieval Fatimid and Mamluk architecture, connecting Bab al-Futuh in the north with Bab Zuweila in the south.', 'متحف مفتوح للعمارة الفاطمية والمملوكية، يمتد من باب الفتوح شمالاً إلى باب زويلة جنوباً ويضم آثاراً إسلامية فريدة.', 'https://upload.wikimedia.org/wikipedia/commons/3/33/Al-Muizz_Street%2C_Old_Cairo%2C_al-Q%C4%81hirah%2C_CG%2C_EGY_%2847859477762%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original', ARRAY['https://upload.wikimedia.org/wikipedia/commons/3/33/Al-Muizz_Street%2C_Old_Cairo%2C_al-Q%C4%81hirah%2C_CG%2C_EGY_%2847859477762%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original']::text[], 4.8, 'Historical', 'تاريخي', 30.0511, 31.2616, 'Al-Gamaliya, Cairo', 'الجمالية، القاهرة', 'Open 24 hours', 7200, 'free', 'Street access is free; some monuments require tickets', 0, 0, FALSE, FALSE, 999, TRUE, TRUE, 'cairo'),
  ('egyptian_museum_tahrir', 'The Egyptian Museum in Cairo', 'The Egyptian Museum in Cairo', 'المتحف المصري بالتحرير', 'An iconic neoclassical museum on Tahrir Square with a major collection of Pharaonic antiquities spanning Egypt’s ancient dynasties.', 'An iconic neoclassical museum on Tahrir Square with a major collection of Pharaonic antiquities spanning Egypt’s ancient dynasties.', 'متحف كلاسيكي الطراز في ميدان التحرير يضم مجموعة بارزة من الآثار الفرعونية التي تمتد عبر عصور مصر القديمة.', 'https://upload.wikimedia.org/wikipedia/commons/5/5d/By_ovedc_-_Egyptian_Museum_%28Cairo%29_-_048.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original', ARRAY['https://upload.wikimedia.org/wikipedia/commons/5/5d/By_ovedc_-_Egyptian_Museum_%28Cairo%29_-_048.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original']::text[], 4.7, 'Culture', 'ثقافة', 30.0478, 31.2336, 'Tahrir Square, Downtown Cairo', 'ميدان التحرير، وسط القاهرة', '9:00 AM - 5:00 PM', 15000, 'cheap', 'Paid admission; verify current ticket prices', 30, 450, FALSE, FALSE, 999, TRUE, TRUE, 'cairo'),
  ('nmec_fustat', 'National Museum of Egyptian Civilization (NMEC)', 'National Museum of Egyptian Civilization (NMEC)', 'المتحف القومي للحضارة المصرية', 'A Fustat museum presenting Egyptian civilization across eras, including the Royal Mummies Hall and collections from prehistoric times to the present.', 'A Fustat museum presenting Egyptian civilization across eras, including the Royal Mummies Hall and collections from prehistoric times to the present.', 'متحف في الفسطاط يعرض حضارة مصر عبر العصور، ويضم قاعة المومياوات الملكية ومجموعات تمتد من عصور ما قبل التاريخ حتى العصر الحديث.', 'https://upload.wikimedia.org/wikipedia/commons/f/fd/National_Museum_of_Egyptian_Civilization_2025_01.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original', ARRAY['https://upload.wikimedia.org/wikipedia/commons/f/fd/National_Museum_of_Egyptian_Civilization_2025_01.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original']::text[], 4.8, 'Culture', 'ثقافة', 30.0084, 31.2482, 'Fustat, Old Cairo', 'الفسطاط، مصر القديمة', '9:00 AM - 5:00 PM', 6800, 'cheap', 'Paid admission; verify current ticket prices', 30, 500, FALSE, FALSE, 999, TRUE, TRUE, 'cairo'),
  ('cairo_tower', 'Cairo Tower', 'Cairo Tower', 'برج القاهرة', 'A 187-metre lotus-inspired tower on Gezira Island, completed in 1961, with 360-degree views over the Nile and the city.', 'A 187-metre lotus-inspired tower on Gezira Island, completed in 1961, with 360-degree views over the Nile and the city.', 'برج بارتفاع ١٨٧ متراً مستوحى من زهرة اللوتس في جزيرة الجزيرة، افتُتح عام ١٩٦١ ويوفر إطلالة بانورامية على النيل والقاهرة.', 'https://upload.wikimedia.org/wikipedia/commons/6/6c/Cairo%2C_Tower_of_Cairo%2C_Egypt%2C_Oct_2004.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original', ARRAY['https://upload.wikimedia.org/wikipedia/commons/6/6c/Cairo%2C_Tower_of_Cairo%2C_Egypt%2C_Oct_2004.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original']::text[], 4.5, 'Historical', 'معلم', 30.0459, 31.2243, 'Gezira Island, Zamalek, Cairo', 'جزيرة الجزيرة، الزمالك، القاهرة', '9:00 AM - 1:00 AM', 8700, 'moderate', 'Paid admission; verify current ticket prices', 70, 250, FALSE, FALSE, 999, TRUE, TRUE, 'cairo'),
  ('sultan_hassan_mosque', 'Mosque-Madrasa of Sultan Hassan', 'Mosque-Madrasa of Sultan Hassan', 'مسجد ومدرسة السلطان حسن', 'A monumental 14th-century Mamluk mosque and madrasa, celebrated for its scale and stonework opposite Citadel Square.', 'A monumental 14th-century Mamluk mosque and madrasa, celebrated for its scale and stonework opposite Citadel Square.', 'مسجد ومدرسة مملوكية ضخمة من القرن الرابع عشر، تشتهر بعظمتها ونقوشها الحجرية وتقع قبالة ميدان القلعة.', 'https://upload.wikimedia.org/wikipedia/commons/3/36/Madrassa_of_Sultan_Hassan.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original', ARRAY['https://upload.wikimedia.org/wikipedia/commons/3/36/Madrassa_of_Sultan_Hassan.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original']::text[], 4.8, 'Mosques', 'مساجد', 30.0316, 31.2561, 'Al-Khalifa, Cairo', 'الخليفة، القاهرة', '9:00 AM - 5:00 PM', 4100, 'cheap', 'Paid admission; respect prayer times', 20, 180, FALSE, FALSE, 999, TRUE, TRUE, 'cairo'),
  ('ibn_tulun_mosque', 'Mosque of Ibn Tulun', 'Mosque of Ibn Tulun', 'مسجد أحمد بن طولون', 'Founded in 879 AD, this is Cairo’s oldest intact mosque, known for its expansive courtyard and distinctive external spiral minaret.', 'Founded in 879 AD, this is Cairo’s oldest intact mosque, known for its expansive courtyard and distinctive external spiral minaret.', 'تأسس المسجد عام ٨٧٩م، ويُعد أقدم مسجد قائم في القاهرة، ويشتهر بصحنه الواسع ومئذنته الحلزونية الخارجية.', 'https://upload.wikimedia.org/wikipedia/commons/b/b3/%D8%A3%D8%AD%D9%85%D8%AF_%D8%A8%D9%86_%D8%B7%D9%88%D9%84%D9%88%D9%86.png?utm_source=ar.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled', ARRAY['https://upload.wikimedia.org/wikipedia/commons/b/b3/%D8%A3%D8%AD%D9%85%D8%AF_%D8%A8%D9%86_%D8%B7%D9%88%D9%84%D9%88%D9%86.png?utm_source=ar.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled']::text[], 4.7, 'Mosques', 'مساجد', 30.0287, 31.2494, 'Al-Sayeda Zainab, Cairo', 'السيدة زينب، القاهرة', '8:00 AM - 5:00 PM', 3200, 'free', 'Free entry; donations welcome', 0, 0, FALSE, FALSE, 999, TRUE, TRUE, 'cairo'),
  ('al_azhar_mosque', 'Al-Azhar Mosque', 'Al-Azhar Mosque', 'الجامع الأزهر', 'Founded in 970 AD as the centre of Fatimid Cairo, Al-Azhar became a world-renowned institution of Islamic learning and worship.', 'Founded in 970 AD as the centre of Fatimid Cairo, Al-Azhar became a world-renowned institution of Islamic learning and worship.', 'تأسس الجامع الأزهر عام ٩٧٠م في قلب القاهرة الفاطمية، وأصبح منارة عالمية للعلم الإسلامي ومكاناً للعبادة.', 'https://upload.wikimedia.org/wikipedia/commons/c/c8/Al-Azhar_Mosque_%288590203917%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original', ARRAY['https://upload.wikimedia.org/wikipedia/commons/c/c8/Al-Azhar_Mosque_%288590203917%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original']::text[], 4.8, 'Mosques', 'مساجد', 30.0457, 31.2627, 'Al-Azhar Street, Cairo', 'شارع الأزهر، القاهرة', 'Prayer times; visitor access varies', 5600, 'free', 'Free entry; respect prayer times and visitor guidance', 0, 0, FALSE, FALSE, 999, TRUE, TRUE, 'cairo'),
  ('hanging_church', 'The Hanging Church', 'The Hanging Church', 'الكنيسة المعلقة', 'A landmark Coptic church built above the gatehouse towers of the Roman Babylon Fortress, with a history reaching back to early Christian Cairo.', 'A landmark Coptic church built above the gatehouse towers of the Roman Babylon Fortress, with a history reaching back to early Christian Cairo.', 'كنيسة قبطية بارزة أُقيمت فوق برجي بوابة حصن بابليون الروماني، ويرتبط تاريخها ببدايات المسيحية في القاهرة.', 'https://upload.wikimedia.org/wikipedia/commons/8/8e/Cairo%2C_Old_Cairo%2C_Hanging_Church%2C_Egypt%2C_Oct_2004_edit.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled', ARRAY['https://upload.wikimedia.org/wikipedia/commons/8/8e/Cairo%2C_Old_Cairo%2C_Hanging_Church%2C_Egypt%2C_Oct_2004_edit.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled']::text[], 4.8, 'Churches', 'كنائس', 30.0053, 31.2302, 'Coptic Cairo, Old Cairo', 'القاهرة القبطية، مصر القديمة', '9:00 AM - 4:00 PM', 4500, 'free', 'Free entry; opening hours may vary', 0, 0, FALSE, FALSE, 999, TRUE, TRUE, 'cairo'),
  ('coptic_museum', 'Coptic Museum', 'Coptic Museum', 'المتحف القبطي', 'A museum with one of the world’s largest collections of Coptic Christian art, including woodwork, textiles, icons, and manuscripts.', 'A museum with one of the world’s largest collections of Coptic Christian art, including woodwork, textiles, icons, and manuscripts.', 'متحف يضم واحدة من أكبر مجموعات الفن القبطي المسيحي في العالم، بما فيها المشغولات الخشبية والمنسوجات والأيقونات والمخطوطات.', 'https://upload.wikimedia.org/wikipedia/commons/e/e9/Cairo_Coptic_Museum.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original', ARRAY['https://upload.wikimedia.org/wikipedia/commons/e/e9/Cairo_Coptic_Museum.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original']::text[], 4.7, 'Culture', 'ثقافة', 30.006, 31.2305, 'Coptic Cairo, Old Cairo', 'القاهرة القبطية، مصر القديمة', '9:00 AM - 5:00 PM', 2300, 'cheap', 'Paid admission; verify current ticket prices', 10, 100, FALSE, FALSE, 999, TRUE, TRUE, 'cairo'),
  ('amr_ibn_alas_mosque', 'Mosque of Amr ibn al-As', 'Mosque of Amr ibn al-As', 'مسجد عمرو بن العاص', 'Originally founded in 641 AD in Fustat, this historic mosque is regarded as the first mosque in Egypt and Africa.', 'Originally founded in 641 AD in Fustat, this historic mosque is regarded as the first mosque in Egypt and Africa.', 'تأسس المسجد في الفسطاط عام ٦٤١م، ويُعرف بأنه أول مسجد في مصر وأفريقيا.', 'https://upload.wikimedia.org/wikipedia/commons/f/f2/Amr_Ibn_al-Aas_Mosque_Interior.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original', ARRAY['https://upload.wikimedia.org/wikipedia/commons/f/f2/Amr_Ibn_al-Aas_Mosque_Interior.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original']::text[], 4.7, 'Mosques', 'مساجد', 30.0101, 31.2332, 'Fustat, Old Cairo', 'الفسطاط، مصر القديمة', 'Prayer times; visitor access varies', 2800, 'free', 'Free entry; respect prayer times', 0, 0, FALSE, FALSE, 999, TRUE, TRUE, 'cairo'),
  ('baron_empain_palace', 'Baron Empain Palace', 'Baron Empain Palace', 'قصر البارون إمبان', 'A distinctive Hindu-temple-inspired palace built for Édouard Empain, founder of Heliopolis, and an architectural landmark of early 20th-century Cairo.', 'A distinctive Hindu-temple-inspired palace built for Édouard Empain, founder of Heliopolis, and an architectural landmark of early 20th-century Cairo.', 'قصر فريد مستوحى من المعابد الهندية شُيّد لإدوار إمبان مؤسس هليوبوليس، ويُعد معلماً معمارياً من أوائل القرن العشرين.', 'https://upload.wikimedia.org/wikipedia/commons/2/2e/Baron_Empain_Palace_Interior_05.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original', ARRAY['https://upload.wikimedia.org/wikipedia/commons/2/2e/Baron_Empain_Palace_Interior_05.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original']::text[], 4.6, 'Historical', 'تاريخي', 30.0867, 31.3303, 'El-Orouba Street, Heliopolis', 'شارع العروبة، مصر الجديدة', '9:00 AM - 6:00 PM', 3900, 'cheap', 'Paid admission; verify current ticket prices', 20, 100, FALSE, FALSE, 999, TRUE, TRUE, 'cairo'),
  ('abdeen_palace', 'Abdeen Palace Museum', 'Abdeen Palace Museum', 'متحف قصر عابدين', 'A 19th-century Khedivial royal palace in Downtown Cairo, now housing specialized museums of royal collections, arms, and historical gifts.', 'A 19th-century Khedivial royal palace in Downtown Cairo, now housing specialized museums of royal collections, arms, and historical gifts.', 'قصر ملكي خديوي من القرن التاسع عشر في وسط القاهرة، ويضم اليوم متاحف متخصصة للمقتنيات الملكية والأسلحة والهدايا التاريخية.', 'https://upload.wikimedia.org/wikipedia/commons/1/17/Abdeen_Palace.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original', ARRAY['https://upload.wikimedia.org/wikipedia/commons/1/17/Abdeen_Palace.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original']::text[], 4.5, 'Culture', 'ثقافة', 30.0429, 31.2476, 'Abdeen Square, Downtown Cairo', 'ميدان عابدين، وسط القاهرة', '9:00 AM - 3:00 PM', 1500, 'cheap', 'Paid admission; verify current visiting arrangements', 20, 100, FALSE, FALSE, 999, TRUE, TRUE, 'cairo'),
  ('al_azhar_park', 'Al-Azhar Park', 'Al-Azhar Park', 'حديقة الأزهر', 'A landscaped hilltop green space with views of the Ayyubid wall and Salah El-Din Citadel, created on the historic edge of Fatimid Cairo.', 'A landscaped hilltop green space with views of the Ayyubid wall and Salah El-Din Citadel, created on the historic edge of Fatimid Cairo.', 'مساحة خضراء منسقة على تلة تطل على سور القاهرة الأيوبي وقلعة صلاح الدين، وتقع عند الحافة التاريخية للقاهرة الفاطمية.', 'https://upload.wikimedia.org/wikipedia/commons/7/77/AZHAR-park.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original', ARRAY['https://upload.wikimedia.org/wikipedia/commons/7/77/AZHAR-park.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original']::text[], 4.6, 'Nature', 'طبيعة', 30.0407, 31.2657, 'Al-Darb Al-Ahmar, Cairo', 'الدرب الأحمر، القاهرة', '9:00 AM - 10:00 PM', 6100, 'cheap', 'Paid park admission; verify current prices', 25, 25, FALSE, FALSE, 999, TRUE, TRUE, 'cairo'),
  ('islamic_art_museum', 'Museum of Islamic Art', 'Museum of Islamic Art', 'متحف الفن الإسلامي', 'A leading museum in Bab Al-Khalq presenting Islamic art and craftsmanship, with notable ceramics, glass lamps, metalwork, and manuscripts.', 'A leading museum in Bab Al-Khalq presenting Islamic art and craftsmanship, with notable ceramics, glass lamps, metalwork, and manuscripts.', 'متحف رائد في باب الخلق يعرض الفن والحرف الإسلامية، ويضم قطعاً مميزة من الخزف والمصابيح الزجاجية والمعادن والمخطوطات.', 'https://upload.wikimedia.org/wikipedia/commons/a/ab/Museum_of_Islamic_Art.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original', ARRAY['https://upload.wikimedia.org/wikipedia/commons/a/ab/Museum_of_Islamic_Art.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original']::text[], 4.7, 'Culture', 'ثقافة', 30.0444, 31.2524, 'Bab Al-Khalq, Cairo', 'باب الخلق، القاهرة', '9:00 AM - 5:00 PM', 1900, 'cheap', 'Paid admission; verify current ticket prices', 20, 100, FALSE, FALSE, 999, TRUE, TRUE, 'cairo'),
  ('gayer_anderson_museum', 'Gayer-Anderson Museum', 'Gayer-Anderson Museum', 'متحف جاير أندرسون (بيت الكريتلية)', 'Two adjoining historic houses from the 16th and 17th centuries beside Ibn Tulun Mosque, noted for Ottoman interiors and intricate mashrabiya screens.', 'Two adjoining historic houses from the 16th and 17th centuries beside Ibn Tulun Mosque, noted for Ottoman interiors and intricate mashrabiya screens.', 'بيتان تاريخيان متجاوران من القرنين السادس عشر والسابع عشر بجوار مسجد ابن طولون، يشتهران بديكورات عثمانية ومشربيات دقيقة الصنع.', 'https://upload.wikimedia.org/wikipedia/commons/e/e1/Egyptian_antiques_collection_at_Gayer-Anderson_Museum-_EWUG_01.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original', ARRAY['https://upload.wikimedia.org/wikipedia/commons/e/e1/Egyptian_antiques_collection_at_Gayer-Anderson_Museum-_EWUG_01.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original']::text[], 4.6, 'Culture', 'ثقافة', 30.0281, 31.2503, 'Al-Sayeda Zainab, Cairo', 'السيدة زينب، القاهرة', '9:00 AM - 5:00 PM', 1100, 'cheap', 'Paid admission; verify current ticket prices', 20, 60, FALSE, FALSE, 999, TRUE, TRUE, 'cairo'),
