INSERT INTO public.tours (
  id, title, title_ar, description, description_ar, duration, duration_ar, category, category_ar, image_url, status, is_premium, is_hidden_gem, governorate
)
VALUES
  ('cairo_islamic_fatimid_walk', 'Fatimid Cairo & Al-Muizz Heritage Walk', 'جولة القاهرة الفاطمية وخان الخليلي', 'Walk the historic lanes of Islamic Cairo, tracing Fatimid and Mamluk landmarks from Al-Muizz Street through Khan El-Khalili and Al-Azhar.', 'جولة سير في أزقة القاهرة الإسلامية بين معالم العصرين الفاطمي والمملوكي، من شارع المعز إلى خان الخليلي والجامع الأزهر وحديقة الأزهر.', '4 hours', '٤ ساعات', 'Heritage', 'تراث', 'https://upload.wikimedia.org/wikipedia/commons/e/ef/Cairo_Citadel_1.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original', 'published', FALSE, FALSE, 'cairo'),
  ('cairo_citadel_fustat_trail', 'Citadel, Coptic Cairo & NMEC Trail', 'مسار القلعة ومجمع الأديان والفسطاط', 'Connect the Citadel and Sultan Hassan Mosque with Coptic Cairo and the NMEC in Fustat for a day spanning Cairo’s medieval and ancient heritage.', 'مسار يربط قلعة صلاح الدين ومسجد السلطان حسن بالقاهرة القبطية ومتحف الحضارة في الفسطاط، في رحلة عبر تراث القاهرة الوسيط والقديم.', 'Full day', 'يوم كامل', 'Heritage', 'تراث', 'https://upload.wikimedia.org/wikipedia/commons/f/fd/National_Museum_of_Egyptian_Civilization_2025_01.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original', 'published', FALSE, FALSE, 'cairo'),
  ('cairo_khedivial_zamalek_nile_tour', 'Khedivial Cairo, Zamalek & the Nile', 'القاهرة الخديوية والزمالك والنيل', 'Discover the Opera House and Zamalek’s gardens before following the Nile through Cairo’s island and riverfront landmarks.', 'اكتشف دار الأوبرا وحدائق الزمالك، ثم اتبع النيل بين معالم الجزيرة وضفاف القاهرة.', 'Full day', 'يوم كامل', 'Heritage', 'تراث', 'https://upload.wikimedia.org/wikipedia/commons/c/c3/Cairo_opera_house.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled', 'published', FALSE, FALSE, 'cairo'),
  ('cairo_heliopolis_nasr_new_cairo_tour', 'Heliopolis, Nasr City & New Cairo', 'مصر الجديدة ومدينة نصر والقاهرة الجديدة', 'Explore Heliopolis heritage, eastern Cairo parks and landmarks, then continue to New Cairo’s contemporary districts.', 'استكشف تراث مصر الجديدة وحدائق ومعالم شرق القاهرة، ثم تابع إلى أحياء القاهرة الجديدة.', 'Full day', 'يوم كامل', 'Heritage', 'تراث', 'https://upload.wikimedia.org/wikipedia/commons/2/2e/Baron_Empain_Palace_Interior_05.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original', 'published', FALSE, FALSE, 'cairo'),
  ('cairo_new_capital_mokattam_wadi_degla', 'New Capital, Mokattam & Wadi Degla', 'العاصمة الإدارية والمقطم ومحمية وادي دجلة', 'Connect the New Administrative Capital’s major landmarks with the Cave Church at Mokattam and Wadi Degla’s protected landscape.', 'اربط معالم العاصمة الإدارية الكبرى بكنيسة الكهف في المقطم والمشهد الطبيعي المحمي في وادي دجلة.', 'Full day', 'يوم كامل', 'Heritage', 'تراث', 'https://upload.wikimedia.org/wikipedia/en/1/17/Iconic_Tower_Egypt%2818-6-2023%29_%28cropped%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled', 'published', FALSE, FALSE, 'cairo')
